<style>.ca-page{color:#203346}.ca-head{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:20px}.ca-head p{margin:4px 0 0;color:#748390;font-size:13px}.ca-head h3,.ca-head h4{margin:0;font-weight:700}.ca-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:18px}.ca-stats>div{background:white;border:1px solid #dce6ee;border-radius:10px;padding:18px}.ca-stats small,.ca-stats strong{display:block}.ca-stats strong{font-size:23px;margin-top:5px}.ca-stats>div:last-child{background:#ecf7f1}#ca-dialog{width:min(700px,94vw);border:0;border-radius:12px;padding:24px;max-height:92dvh;overflow:auto}#ca-dialog::backdrop{background:#142d466b}@media(max-width:600px){.ca-stats{grid-template-columns:1fr}.ca-head{align-items:flex-start}}</style>
<script>
(function(){const dialog=document.getElementById('ca-dialog'),form=document.getElementById('ca-form'),rows={{ \Illuminate\Support\Js::from($editRows) }},store={{ \Illuminate\Support\Js::from(route('contractor-advances.store')) }};
document.getElementById('ca-add').addEventListener('click',()=>{form.reset();form.action=store;form.elements._method.value='POST';document.getElementById('ca-title').textContent='Add Contractor Advance';dialog.showModal();});document.getElementById('ca-close').addEventListener('click',()=>dialog.close());document.querySelectorAll('[data-ca-edit]').forEach(button=>button.addEventListener('click',()=>{const row=rows.find(r=>String(r.id)===button.dataset.caEdit);form.reset();for(const [key,value] of Object.entries(row))if(form.elements.namedItem(key))form.elements.namedItem(key).value=value??'';form.action=store+'/'+row.id;form.elements._method.value='PUT';document.getElementById('ca-title').textContent='Edit Contractor Advance';dialog.showModal();}));document.getElementById('ca-search').addEventListener('input',function(){const q=this.value.toLowerCase().trim();document.querySelectorAll('[data-ca-name]').forEach(row=>row.hidden=!row.dataset.caName.includes(q));});form.addEventListener('submit',()=>{form.querySelector('button[type=submit]').disabled=true;});})();
</script>
